import java.util.*;
public final class InorderWriterValidation {
    static List<Integer> oracle(Solution.TreeNode n){List<Integer> out=new ArrayList<>();oracle(n,out);return out;}static void oracle(Solution.TreeNode n,List<Integer> out){if(n==null)return;oracle(n.left,out);out.add(n.val);oracle(n.right,out);}
    static Solution.TreeNode fromMask(int mask,int slots){Solution.TreeNode[] n=new Solution.TreeNode[slots];for(int i=0;i<slots;i++)if(((mask>>>i)&1)!=0)n[i]=new Solution.TreeNode(i*17-31);if(n[0]==null)return null;for(int i=0;i<slots;i++)if(n[i]!=null){int l=2*i+1,r=2*i+2;if(l<slots)n[i].left=n[l];if(r<slots)n[i].right=n[r];}return n[0];}
    static int count(Solution.TreeNode n){return n==null?0:1+count(n.left)+count(n.right);}static void check(Solution.TreeNode root){List<Integer>want=oracle(root),a=Solution.inorderRecursive(root),b=Solution.inorderIterative(root);if(!a.equals(want)||!b.equals(want)||a.size()!=count(root))throw new AssertionError("mismatch want="+want+" rec="+a+" iter="+b);}
    static Solution.TreeNode randomTree(Random r,int n){if(n==0)return null;List<Solution.TreeNode> nodes=new ArrayList<>();Solution.TreeNode root=new Solution.TreeNode(r.nextInt());nodes.add(root);for(int i=1;i<n;i++){Solution.TreeNode x=new Solution.TreeNode(r.nextInt());for(;;){Solution.TreeNode p=nodes.get(r.nextInt(nodes.size()));if(r.nextBoolean()){if(p.left==null){p.left=x;break;}}else if(p.right==null){p.right=x;break;}}nodes.add(x);}return root;}
    public static void main(String[] args){check(null);Solution.TreeNode root=new Solution.TreeNode(1);root.left=new Solution.TreeNode(2);root.right=new Solution.TreeNode(3);root.left.right=new Solution.TreeNode(4);check(root);long masks=0;for(int mask=1;mask<(1<<11);mask++){check(fromMask(mask,11));masks++;}Random r=new Random(0x1A0D3EL);for(int t=0;t<10000;t++)check(randomTree(r,r.nextInt(100)));System.out.println("PASS fixed=2 masks="+masks+" random=10000 recursive=iterative=oracle null+balanced+skew-capable=covered");}
}
